// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(address recipient, uint256 tokenId, uint256 quantity) public {
        vm.assume(recipient != address(0));
        vm.assume(quantity > 0);

        c.createGameItem("itm", "uri", false, true, 0, 1, 1);

        vm.assume(tokenId == 0);

        TestNeuron nrn = new TestNeuron();
        c.instantiateNeuronContract(address(nrn));

        nrn.setBalance(recipient, quantity);

        vm.prank(recipient);
        try c.mint(tokenId, quantity) {
        } catch {
            return;
        }

        uint256 bal = c.balanceOf(recipient, tokenId);
        assertTrue(bal > 0);
    }
}

contract TestNeuron {
    mapping(address => uint256) public balances;
    function setBalance(address who, uint256 amount) external { balances[who] = amount; }
    function balanceOf(address who) external view returns (uint256) { return balances[who]; }
    function approveSpender(address account, uint256 amount) external {
        return;
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (balances[from] < amount) return false;
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }
}
